//============================================================
// ============================================================
// pool_wrapper.v
// ------------------------------------------------------------
// Scans over an input feature map and applies 2x2 max-pooling
// with stride 2, writing the downsampled result back to the
// feature buffer via the write-side interface.
//
// The pure maxpool2x2 module only computes max(4 inputs) in a
// single combinational step. This wrapper is what makes it
// actually useful: it drives addresses into the feature buffer,
// gathers the 4 pixels of each 2x2 window, invokes maxpool2x2,
// and writes the result.
//
// Supports:
//   - arbitrary IN_H, IN_W (must be even), IN_CH
//   - output is IN_H/2 x IN_W/2 x IN_CH
//   - same address layout convention as conv_engine:
//     read addr  = (ic * IN_H * IN_W) + (row * IN_W) + col
//     write addr = (ic * OUT_H * OUT_W) + (orow * OUT_W) + ocol
//
// Pipeline per output pixel (6 cycles):
//   S_ISSUE_TL -> S_WAIT_TL -> capture a00
//   S_ISSUE_TR -> S_WAIT_TR -> capture a01
//   S_ISSUE_BL -> S_WAIT_BL -> capture a10
//   S_ISSUE_BR -> S_WAIT_BR -> capture a11
//   S_COMPUTE  -> write max to output address
//
// (We use a single S_ISSUE state with a 2-bit sub-counter for
//  compactness, but the behaviour is equivalent.)
// ============================================================

`timescale 1ns / 1ps

module pool_wrapper #(
    parameter integer IN_H     = 28,
    parameter integer IN_W     = 28,
    parameter integer IN_CH    = 6,
    parameter integer OUT_H    = 14,     // = IN_H / 2
    parameter integer OUT_W    = 14,     // = IN_W / 2
    parameter integer DATA_W   = 8,
    parameter integer FADDR_W  = 13,
    parameter integer OADDR_W  = 13
)(
    input  wire                       clk,
    input  wire                       rst_n,
    input  wire                       start,

    // feature_buffer read side (sync, 1-cycle latency)
    output reg  [FADDR_W-1:0]         fmap_addr,
    input  wire signed [DATA_W-1:0]   fmap_in,

    // feature_buffer write side
    output reg  [OADDR_W-1:0]         out_addr,
    output reg  signed [DATA_W-1:0]   out_data,
    output reg                        out_en,

    output reg                        done
);

    // =========================================================
    // FSM states
    // =========================================================
    localparam S_IDLE     = 4'd0;
    localparam S_ISSUE    = 4'd1;  // issue addr for one of 4 corners
    localparam S_WAIT     = 4'd2;  // wait 1 cycle for sync read
    localparam S_CAPTURE  = 4'd3;  // capture fmap_in into correct slot
    localparam S_COMPUTE  = 4'd4;  // write max to output
    localparam S_DONE     = 4'd5;

    reg [3:0] state, next_state;

    // =========================================================
    // Loop counters
    //   ic (outer):   0..IN_CH-1
    //   or (mid):     0..OUT_H-1
    //   oc (inner):   0..OUT_W-1
    // Plus a 2-bit sub-counter to iterate through the 4 corners
    // =========================================================
    reg [7:0]  ic_cnt;
    reg [15:0] or_cnt;
    reg [15:0] oc_cnt;
    reg [1:0]  corner_cnt;       // 0=TL, 1=TR, 2=BL, 3=BR

    wire last_corner = (corner_cnt == 2'd3);
    wire last_oc     = (oc_cnt == OUT_W - 1);
    wire last_or     = (or_cnt == OUT_H - 1);
    wire last_ic     = (ic_cnt == IN_CH - 1);
    wire all_done    = last_oc && last_or && last_ic;

    // =========================================================
    // Four registers to hold the 2x2 window values
    // =========================================================
    reg signed [DATA_W-1:0] a00, a01, a10, a11;

    // =========================================================
    // Instance of the combinational maxpool
    // =========================================================
    wire signed [DATA_W-1:0] pool_result;

    maxpool2x2 #(.WIDTH(DATA_W)) u_pool (
        .a00(a00), .a01(a01),
        .a10(a10), .a11(a11),
        .dout(pool_result)
    );

    // =========================================================
    // Next-state logic
    // =========================================================
    always @(*) begin
        next_state = state;
        case (state)
            S_IDLE:    if (start)          next_state = S_ISSUE;
            S_ISSUE:                        next_state = S_WAIT;
            S_WAIT:                         next_state = S_CAPTURE;
            S_CAPTURE: begin
                if (last_corner)            next_state = S_COMPUTE;
                else                        next_state = S_ISSUE;
            end
            S_COMPUTE: begin
                if (all_done)               next_state = S_DONE;
                else                        next_state = S_ISSUE;
            end
            S_DONE:                         next_state = S_IDLE;
            default:                        next_state = S_IDLE;
        endcase
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) state <= S_IDLE;
        else        state <= next_state;
    end

    // =========================================================
    // Counter updates
    // =========================================================
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            ic_cnt     <= 0;
            or_cnt     <= 0;
            oc_cnt     <= 0;
            corner_cnt <= 0;
        end else begin
            // Corner counter: advances in S_CAPTURE
            if (state == S_CAPTURE) begin
                if (last_corner) corner_cnt <= 0;
                else             corner_cnt <= corner_cnt + 1;
            end

            // Outer counters advance on S_COMPUTE -> S_ISSUE transition
            if (state == S_COMPUTE && next_state == S_ISSUE) begin
                corner_cnt <= 0;
                if (last_oc) begin
                    oc_cnt <= 0;
                    if (last_or) begin
                        or_cnt <= 0;
                        ic_cnt <= ic_cnt + 1;
                    end else begin
                        or_cnt <= or_cnt + 1;
                    end
                end else begin
                    oc_cnt <= oc_cnt + 1;
                end
            end

            // Reset counters on start
            if (state == S_IDLE && start) begin
                ic_cnt     <= 0;
                or_cnt     <= 0;
                oc_cnt     <= 0;
                corner_cnt <= 0;
            end
        end
    end

    // =========================================================
    // Address generation
    // For stride=2, the 2x2 window top-left is at (or*2, oc*2).
    // The 4 corners are (or*2+dr, oc*2+dc) for (dr,dc) in
    //   (0,0), (0,1), (1,0), (1,1) selected by corner_cnt.
    // =========================================================
    wire [15:0] in_row = (or_cnt << 1) + {15'd0, corner_cnt[1]};
    wire [15:0] in_col = (oc_cnt << 1) + {15'd0, corner_cnt[0]};

    wire [31:0] f_addr_full = (ic_cnt * IN_H * IN_W) +
                              (in_row * IN_W) +
                              in_col;

    wire [31:0] o_addr_full = (ic_cnt * OUT_H * OUT_W) +
                              (or_cnt * OUT_W) +
                              oc_cnt;

    always @(*) begin
        fmap_addr = f_addr_full[FADDR_W-1:0];
    end

    // =========================================================
    // Capture window values
    // The sync read delivers fmap_in one cycle after we issued
    // the address, so in S_CAPTURE fmap_in is the value for the
    // corner indexed by corner_cnt.
    // =========================================================
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            a00 <= 0; a01 <= 0; a10 <= 0; a11 <= 0;
        end else begin
            if (state == S_CAPTURE) begin
                case (corner_cnt)
                    2'd0: a00 <= fmap_in;
                    2'd1: a01 <= fmap_in;
                    2'd2: a10 <= fmap_in;
                    2'd3: a11 <= fmap_in;
                endcase
            end
        end
    end

    // =========================================================
    // Output write (in S_COMPUTE)
    // =========================================================
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            out_data <= 0;
            out_addr <= 0;
            out_en   <= 1'b0;
        end else begin
            if (state == S_COMPUTE) begin
                out_data <= pool_result;
                out_addr <= o_addr_full[OADDR_W-1:0];
                out_en   <= 1'b1;
            end else begin
                out_en   <= 1'b0;
            end
        end
    end

    // =========================================================
    // Done pulse
    // =========================================================
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)                done <= 1'b0;
        else if (state == S_DONE)  done <= 1'b1;
        else                       done <= 1'b0;
    end

endmodule
